import sys
from pathlib import Path

from extract3 import ocr_variants, extract_date, extract_total


def dump(path):
    results = ocr_variants(path)
    print(f"====== {path.name} ======")
    for i, (label, text) in enumerate(results):
        d = extract_date(text)
        t = extract_total(text)
        print(f"--- Variant {i}: {label}  -> date={d} total={t}")
        for ln in text.splitlines():
            if ln.strip():
                print(f"  {ln}")
        print()


for p in sys.argv[1:]:
    dump(Path(p))
