TIME_RE = re.compile(r"\b\d{1,2}[:.]\d{2}(?:[:.]\d{2})?\s*(?:AM|PM|am|pm)?\b")


def extract_date(text: str):
    lines = text.splitlines()
    n = len(lines)
    scored = []
    for i, line in enumerate(lines):
        cands = _date_candidates(line)
        if not cands:
            continue
        labeled = bool(DATE_LABEL_RE.search(line))
        time_present = bool(TIME_RE.search(line))
        neighbor = ""
        for j in (i - 1, i + 1):
            if 0 <= j < n:
                neighbor += " " + lines[j]
        labeled_near = labeled or bool(DATE_LABEL_RE.search(neighbor))
        time_near = time_present or bool(TIME_RE.search(neighbor))
        header = i < max(15, n // 2)
        for ymd in cands:
            score = 0
            if labeled:
                score += 50
            elif labeled_near:
                score += 20
            if time_present:
                score += 15
            elif time_near:
                score += 5
            if header:
                score += 10
            score += max(0, 5 - i // 5)
            scored.append((score, i, ymd))
    if not scored:
        return None
    scored.sort(key=lambda t: (-t[0], t[1]))
