def score_dates(text: str):
    """Return list of (score, ymd) candidates across all lines of ``text``."""
    lines = text.splitlines()
    n = len(lines)
    scored = []
    for i, line in enumerate(lines):
        cands = _date_candidates(line)
        if not cands:
            continue
        labeled = bool(DATE_LABEL_RE.search(line))
        time_here = bool(TIME_RE.search(line))
        neighbor = ""
