        time_near = time_here or bool(TIME_RE.search(neighbor))
        header = i < max(15, n // 2)
        for ymd in cands:
            score = 0
            if labeled:
                score += 50
            elif labeled_near:
                score += 20
            if time_here:
                score += 15
            elif time_near:
                score += 5
            if header:
                score += 10
            score += max(0, 5 - i // 5)
