    m = re.fullmatch(r"-?(\d+)(?:\.(\d{1,2}))?", s)
    if not m:
        return None
    whole = int(m.group(1))
    frac = (m.group(2) or "00").ljust(2, "0")[:2]
    if whole < 0:
        return None
    return f"{whole}.{frac}"


