                neighbor += " " + lines[j]
        labeled_near = labeled or bool(DATE_LABEL_RE.search(neighbor))
        time_near = time_present or bool(TIME_RE.search(neighbor))
        header = i < max(15, n // 2)
        for ymd in cands:
            score = 0
            if labeled:
                score += 50
            elif labeled_near:
                score += 20
            if time_present:
                score += 15
            elif time_near:
                score += 5
            if header:
                score += 10
            score += max(0, 5 - i // 5)
            scored.append((score, i, ymd))
    if not scored:
        return None
    scored.sort(key=lambda t: (-t[0], t[1]))
    y, mo, d = scored[0][2]
    return f"{y:04d}-{mo:02d}-{d:02d}"


# ---------- Total extraction ----------

AMOUNT_RE = re.compile(
    r"(?:(?:RM|RN|R\$|\$)\s*)?"
    r"(-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?"
    r"|-?\d+[.,:;]\d{1,2}(?!\d)"
    r"|-?\d+)"
)


def normalize_amount(raw: str):
    if raw is None:
        return None
    s = raw.strip().replace(" ", "")
    for mark in ("RM", "RN", "R$", "$"):
        s = s.replace(mark, "")
    if not s:
        return None
    if re.fullmatch(r"-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?", s):
        s = s.replace(",", "")
    else:
        s = re.sub(r"([,:;])(\d{1,2})(?!\d)", r".\2", s)
    m = re.fullmatch(r"-?(\d+)(?:\.(\d{1,2}))?", s)
    if not m:
        return None
    whole = int(m.group(1))
    frac = (m.group(2) or "00").ljust(2, "0")[:2]
    if whole < 0:
        return None
    return f"{whole}.{frac}"


def _amounts_in_line(line: str):
    out = []
    for m in AMOUNT_RE.finditer(line):
        raw = m.group(1)
        norm = normalize_amount(raw)
        if norm is None:
            continue
        if "." not in raw and "," not in raw and ":" not in raw and ";" not in raw:
            try:
                iv = int(raw)
            except ValueError:
                iv = None
            if iv is not None:
                if abs(iv) < 10:
                    continue
                if 1900 <= iv <= 2100:
                    continue
        out.append(norm)
    return out


def _has_digit(line: str) -> bool:
    return bool(re.search(r"\d", line))


# --- Tiered keyword patterns ---

TIER_PATTERNS = [
    # Tier 1: GRAND TOTAL (plus obvious OCR glitches)
    [re.compile(r"\bGRAND\s*TOTA[LI1]?\b", re.IGNORECASE),
     re.compile(r"\bGRANDTOTAL\b", re.IGNORECASE)],
    # Tier 2: TOTAL RM / TOTAL: RM / TOTAL(RM)
    [re.compile(r"\bTOTAL\b[\s:()\-]{0,4}R[MN]\b", re.IGNORECASE)],
    # Tier 3: TOTAL AMOUNT
    [re.compile(r"\bTOTAL\s*AMOUNT\b", re.IGNORECASE)],
    # Tier 4: broadest match — TOTAL variants and DUE lines
    [re.compile(r"\bTOTAL\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bAMOUNT\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bBALANCE\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bNETT?\s*TOTAL\b", re.IGNORECASE),
     re.compile(r"\bTOTAL\b", re.IGNORECASE)],
]

# Exclusion patterns. Match the WHOLE line as containing something we skip.
# Note: tightened rules (don't blanket-exclude GST if line is a "Total Inclusive GST").
PLAIN_EXCLUSIONS = re.compile(
    r"\b("
    r"SUB[\s\-]?TOTAL|"
    r"DISCOUNT|"
    r"CHANGE|"
    r"CASH\s*TENDERED|CASH\s*RECEIVED|CASH\s*PAYMENT|"
    r"SAVING|SAVINGS|"
    r"EXCLUDING|EXCL\.?\s*GST|EXCL\.?\s*SST|EXCL\.?\s*TAX|"
    r"TOTAL\s*(ITEM|ITEMS|QTY|QUANTITY)|"
    r"ITEM\s*COUNT|NO\s*OF\s*ITEMS|"
    r"TOTAL\s*(GST|SST|TAX)|"
    r"(GST|SST|TAX)\s*TOTAL|"
    r"TAX\s*CODE|GST\s*CODE|"
    r"SPEC\.?\s*DISC|"
    r"ROUNDING\s*ADJ"
    r")\b",
    re.IGNORECASE,
)

SUMMARY_HEADER_RE = re.compile(
    r"\b(GST|SST|TAX)\s*SUMMARY\b",
    re.IGNORECASE,
)

INCLUSIVE_GST_RE = re.compile(
    r"\b(INCL(?:USIVE|UDING)?|INCL\.?)\b.{0,10}\b(OF\s+)?(GST|SST|TAX)\b",
    re.IGNORECASE,
)

COLUMN_HEADER_HINT_RE = re.compile(
    r"\b(QTY|ITEM|DESCRIPTION|DESC|S/PRICE|U\.?PRICE|U/P|UNIT\s*PRICE|CODE|TAX\s*CODE)\b",
    re.IGNORECASE,
)


def line_is_excluded(line: str) -> bool:
    if PLAIN_EXCLUSIONS.search(line):
        return True
    # Blanket skip tax-only SUMMARY lines (they often have column headers).
    if SUMMARY_HEADER_RE.search(line):
        return True
    return False


def line_is_column_header(line: str) -> bool:
    """Lines that match TOTAL/AMOUNT but are part of an item-table header row."""
    hints = len(COLUMN_HEADER_HINT_RE.findall(line))
    return hints >= 1 and not _has_digit(line)


def classify_lines(lines):
    """Yield (idx, line, excluded, in_summary)."""
    in_summary = False
    for i, ln in enumerate(lines):
        if SUMMARY_HEADER_RE.search(ln):
            in_summary = True
        # Heuristic: leave summary on blank line or header-like content
        if in_summary and not ln.strip():
            in_summary = False
        yield i, ln, line_is_excluded(ln), in_summary


def extract_total(text: str):
    lines = text.splitlines()
    classified = list(classify_lines(lines))
    n = len(lines)

    for tier in TIER_PATTERNS:
        same_line = []
        split_line = []
        for i, line, excluded, in_summary in classified:
            if in_summary:
                continue
            if excluded:
                # Keep a line that has "inclusive GST" even if GST exclusion kicked in.
                # PLAIN_EXCLUSIONS does NOT match "INCL. GST" so an inclusive line
                # won't be excluded to begin with. This guard is defensive.
                continue
            if not any(pat.search(line) for pat in tier):
                continue
            if line_is_column_header(line):
                continue
            amounts = _amounts_in_line(line)
            if amounts:
                same_line.append((i, amounts[-1]))
            elif not _has_digit(line):
                for j in range(i + 1, min(i + 3, n)):
                    nxt = lines[j].strip()
                    if not nxt:
                        continue
                    if line_is_column_header(nxt):
                        break
                    nxt_amounts = _amounts_in_line(nxt)
                    if nxt_amounts:
                        split_line.append((i, nxt_amounts[-1]))
                    break
        if same_line:
            return same_line[-1][1]
        if split_line:
            return split_line[-1][1]
    return None


# ---------- Voting ----------

def pick_best(values):
    seen = {}
    counts = Counter()
    for idx, v in enumerate(values):
        if v is None:
            continue
        counts[v] += 1
        if v not in seen:
            seen[v] = idx
    if not counts:
        return None
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], seen[kv[0]]))
    return ranked[0][0]


def process_image(path: Path):
    results = ocr_variants(path)
    dates = [extract_date(txt) for _, txt in results]
    totals = [extract_total(txt) for _, txt in results]
    return pick_best(dates), pick_best(totals)


def main():
    rows = []
    files = sorted(IMG_DIR.iterdir(), key=lambda p: p.name)
    for p in files:
        if p.suffix.lower() not in {".png", ".jpg", ".jpeg"}:
            continue
        print(f"Processing {p.name}...", file=sys.stderr)
        d, t = process_image(p)
        print(f"  date={d} total={t}", file=sys.stderr)
        rows.append((p.name, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}", file=sys.stderr)


if __name__ == "__main__":
    main()
