{"command": "create", "path": "/app/workspace/extract.py", "file_text": """"OCR-based extraction of date and total amount from Malaysian receipt images.

Writes /app/workspace/stat_ocr.xlsx with a single "results" sheet containing
columns filename, date (ISO), total_amount (two decimals, as string) ordered
by filename.
"""
import re
import sys
from datetime import date as date_type
from pathlib import Path

import pytesseract
from PIL import Image, ImageFilter, ImageOps
from openpyxl import Workbook


IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")


# ---------- OCR ----------

def preprocess_variants(img: Image.Image):
    g = ImageOps.grayscale(img)
    ac = ImageOps.autocontrast(g)
    yield ("gray_ac_psm6", ac, "--psm 6")
    yield ("gray_ac_psm4", ac, "--psm 4")
    yield ("gray_ac_sharp_psm6", ac.filter(ImageFilter.SHARPEN), "--psm 6")
    yield ("raw_default", img, "")
    if min(img.size) < 1200:
        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        yield ("up2_psm6", big, "--psm 6")
        yield ("up2_psm4", big, "--psm 4")


def clean_line(line: str) -> str:
    """Normalise whitespace glitches that break numeric parsing."""
    line = re.sub(r"(\d)\s*\.\s+(\d)", r"\1.\2", line)
    line = re.sub(r"(\d)\s+\.\s*(\d)", r"\1.\2", line)
    line = re.sub(r"(\d)\s*,\s+(\d)", r"\1,\2", line)
    line = re.sub(r"(\d)\s*[:;]\s+(\d{2})\b", r"\1.\2", line)
    return line


def ocr_variants(img_path: Path):
    img = Image.open(img_path)
    out = []
    for label, im, psm in preprocess_variants(img):
        try:
            txt = pytesseract.image_to_string(im, lang="eng", config=psm)
        except Exception:
            txt = ""
        if txt and txt.strip():
            lines = [clean_line(ln) for ln in txt.splitlines()]
            out.append((label, "\n".join(lines)))
    return out


# ---------- Date extraction ----------

DATE_LABEL_RE = re.compile(
    r"\b(BIZ\s*DATE|BIZDATE|BILL\s*D[TI]|BILL\s*DATE|DOC\s*DATE|"
    r"SALES\s*DATE|INVOICE\s*DATE|DATED?|DAIE|DAtE)\b",
    re.IGNORECASE,
)

MONTH_NAMES = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10,
    "november": 11, "december": 12,
}

DATE_SLASH_RE = re.compile(r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})(?!\d)")
DATE_ISO_RE = re.compile(r"(?<!\d)(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})(?!\d)")
DATE_TEXT_RE = re.compile(r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})(?!\d)")
TIME_RE = re.compile(r"\b\d{1,2}[:.]\d{2}(?:[:.]\d{2})?\s*(?:AM|PM|am|pm)?\b")


def _plausible(y: int, m: int, d: int) -> bool:
    if not (2015 <= y <= 2030):
        return False
    try:
        date_type(y, m, d)
    except ValueError:
        return False
    return True


def _date_candidates(line: str):
    out = []
    for m in DATE_ISO_RE.finditer(line):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if _plausible(y, mo, d):
            out.append((y, mo, d))
    for m in DATE_SLASH_RE.finditer(line):
        a, b, c = m.group(1), m.group(2), m.group(3)
        if len(a) == 4:
            continue
        day = int(a)
        mo = int(b)
        y = int(c) if len(c) == 4 else 2000 + int(c)
        if _plausible(y, mo, day):
            out.append((y, mo, day))
        elif _plausible(y, day, mo):
            out.append((y, day, mo))
    for m in DATE_TEXT_RE.finditer(line):
        day = int(m.group(1))
        mo_name = m.group(2).lower()
        if mo_name not in MONTH_NAMES:
            continue
        mo = MONTH_NAMES[mo_name]
        yr = m.group(3)
        y = int(yr) if len(yr) == 4 else 2000 + int(yr)
        if _plausible(y, mo, day):
            out.append((y, mo, day))
    return out


def score_dates(text: str):
    """Return list of (score, ymd) candidates across all lines of ``text``."""
    lines = text.splitlines()
    n = len(lines)
    scored = []
    for i, line in enumerate(lines):
        cands = _date_candidates(line)
        if not cands:
            continue
        labeled = bool(DATE_LABEL_RE.search(line))
        time_here = bool(TIME_RE.search(line))
        neighbor = ""
        for j in (i - 1, i + 1):
            if 0 <= j < n:
                neighbor += " " + lines[j]
        labeled_near = labeled or bool(DATE_LABEL_RE.search(neighbor))
        time_near = time_here or bool(TIME_RE.search(neighbor))
        header = i < max(15, n // 2)
        for ymd in cands:
            score = 0
            if labeled:
                score += 50
            elif labeled_near:
                score += 20
            if time_here:
                score += 15
            elif time_near:
                score += 5
            if header:
                score += 10
            score += max(0, 5 - i // 5)
            # Favour days printed with two digits (OCR may drop leading digit)
            if ymd[2] >= 10:
                score += 1
            scored.append((score, ymd))
    return scored


# ---------- Total extraction ----------

AMOUNT_RE = re.compile(
    r"(?:(?:RM|RN|R\$|\$)\s*)?"
    r"(-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?"
    r"|-?\d+[.,:;]\d{1,2}(?!\d)"
    r"|-?\d+)"
)


def normalize_amount(raw: str):
    if raw is None:
        return None
    s = raw.strip().replace(" ", "")
    for mark in ("RM", "RN", "R$", "$"):
        s = s.replace(mark, "")
    if not s:
        return None
    if re.fullmatch(r"-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?", s):
        s = s.replace(",", "")
    else:
        s = re.sub(r"([,:;])(\d{1,2})(?!\d)", r".\2", s)
    m = re.fullmatch(r"-?(\d+)(?:\.(\d{1,2}))?", s)
    if not m:
        return None
    whole = int(m.group(1))
    frac = (m.group(2) or "00").ljust(2, "0")[:2]
    if whole < 0:
        return None
    return f"{whole}.{frac}"


def _amounts_in_line(line: str):
    """Return normalised amounts found on ``line`` (left-to-right order)."""
    out = []
    for m in AMOUNT_RE.finditer(line):
        start = m.start(1)
        raw = m.group(1)
        # Drop fragments like "§.30" where "30" is really a fractional piece
        # whose integer part was replaced by a non-digit character.
        if start > 0 and line[start - 1] == "." and raw.lstrip("-").isdigit():
            if start < 2 or not line[start - 2].isdigit():
                continue
        norm = normalize_amount(raw)
        if norm is None:
            continue
        # Reject bare integers that are obviously not money (e.g. counts, years)
        if "." not in raw and "," not in raw and ":" not in raw and ";" not in raw:
            try:
                iv = int(raw)
            except ValueError:
                iv = None
            if iv is not None:
                if abs(iv) < 10:
                    continue
                if 1900 <= iv <= 2100:
                    continue
        out.append(norm)
    return out


def _has_digit(line: str) -> bool:
    return bool(re.search(r"\d", line))


TIER_PATTERNS = [
    # Tier 1: GRAND TOTAL (plus common OCR corruption variants)
    [re.compile(r"\bGRAND\s*TOTA[LI1]?\b", re.IGNORECASE),
     re.compile(r"\bGRANDTOTAL\b", re.IGNORECASE)],
    # Tier 2: TOTAL RM / TOTAL: RM / TOTAL(RM) — a few OCR-friendly RM variants
    [re.compile(r"\bTOTAL\b[\s:()\-]{0,4}R[MNH]\b", re.IGNORECASE)],
    # Tier 3: TOTAL AMOUNT
    [re.compile(r"\bTOTAL\s*AMOUNT\b", re.IGNORECASE)],
    # Tier 4: broader TOTAL / DUE variants
    [re.compile(r"\bTOTAL\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bAMOUNT\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bBALANCE\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bNETT?\s*TOTAL\b", re.IGNORECASE),
     re.compile(r"\bTOTAL\b", re.IGNORECASE)],
]

PLAIN_EXCLUSIONS = re.compile(
    r"\b("
    r"SUB[\s\-]?TOTAL|"
    r"DISCOUNT|"
    r"CHANGE|"
    r"CASH\s*TENDERED|CASH\s*RECEIVED|CASH\s*PAYMENT|"
    r"SAVING|SAVINGS|"
    r"EXCLUDING|EXCL\.?\s*(GST|SST|TAX)|"
    r"TOTAL\s*(ITEM|ITEMS|QTY|QUANTITY)|"
    r"ITEM\s*COUNT|NO\s*OF\s*ITEMS|"
    r"TOTAL\s*(GST|SST|TAX)|"
    r"(GST|SST|TAX)\s*TOTAL|"
    r"TAX\s*CODE|GST\s*CODE|"
    r"SPEC\.?\s*DISC|"
    r"ROUNDING\s*ADJ"
    r")\b",
    re.IGNORECASE,
)

SUMMARY_TRIGGER_RE = re.compile(
    r"\b(GST|SST|TAX)\s*(SUMMARY|CODE)\b",
    re.IGNORECASE,
)

COLUMN_HEADER_HINT_RE = re.compile(
    r"\b(QTY|ITEM|DESCRIPTION|DESC|S/PRICE|U\.?PRICE|U/P|UNIT\s*PRICE|CODE)\b",
    re.IGNORECASE,
)


def line_is_excluded(line: str) -> bool:
    return bool(PLAIN_EXCLUSIONS.search(line))


def line_is_column_header(line: str) -> bool:
    """Heuristic: column headers have keyword hints and no numeric values."""
    return bool(COLUMN_HEADER_HINT_RE.search(line)) and not _has_digit(line)


def classify_lines(lines):
    """Yield (idx, line, excluded, in_summary). Once summary begins, it is sticky."""
    in_summary = False
    for i, ln in enumerate(lines):
        if SUMMARY_TRIGGER_RE.search(ln):
            in_summary = True
        yield i, ln, line_is_excluded(ln), in_summary


def extract_total(text: str):
    lines = text.splitlines()
    classified = list(classify_lines(lines))
    n = len(lines)

    for tier in TIER_PATTERNS:
        same_line = []
        split_line = []
        for i, line, excluded, in_summary in classified:
            if in_summary or excluded:
                continue
            if not any(pat.search(line) for pat in tier):
                continue
            if line_is_column_header(line):
                continue
            amounts = _amounts_in_line(line)
            if amounts:
                same_line.append((i, amounts[-1]))
                continue
            # Fallback: last amount on the next non-empty line when this line
            # carries only the label and no usable amount.
            for j in range(i + 1, min(i + 3, n)):
                nxt = lines[j].strip()
                if not nxt:
                    continue
                if line_is_column_header(nxt):
                    break
                nxt_amounts = _amounts_in_line(nxt)
                if nxt_amounts:
                    split_line.append((i, nxt_amounts[-1]))
                break
        if same_line:
            return same_line[-1][1]
        if split_line:
            return split_line[-1][1]
    return None


# ---------- Aggregation across variants ----------

def pick_date(all_scored):
    """Pick best date by total score across variants; tie-break by frequency."""
    totals = {}
    freq = {}
    first_seen = {}
    for var_idx, scored in enumerate(all_scored):
        picked = set()
        for score, ymd in scored:
            totals[ymd] = totals.get(ymd, 0) + score
            if ymd not in first_seen:
                first_seen[ymd] = var_idx
            picked.add(ymd)
        for ymd in picked:
            freq[ymd] = freq.get(ymd, 0) + 1
    if not totals:
        return None
    ranked = sorted(
        totals.items(),
        key=lambda kv: (-kv[1], -freq[kv[0]], first_seen[kv[0]]),
    )
    y, mo, d = ranked[0][0]
    return f"{y:04d}-{mo:02d}-{d:02d}"


def pick_total(values):
    seen = {}
    counts = {}
    for idx, v in enumerate(values):
        if v is None:
            continue
        counts[v] = counts.get(v, 0) + 1
        if v not in seen:
            seen[v] = idx
    if not counts:
        return None
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], seen[kv[0]]))
    return ranked[0][0]


def process_image(path: Path):
    results = ocr_variants(path)
    scored_dates = [score_dates(txt) for _, txt in results]
    totals = [extract_total(txt) for _, txt in results]
    return pick_date(scored_dates), pick_total(totals)


def main():
    rows = []
    files = sorted(IMG_DIR.iterdir(), key=lambda p: p.name)
    for p in files:
        if p.suffix.lower() not in {".png", ".jpg", ".jpeg"}:
            continue
        print(f"Processing {p.name}...", file=sys.stderr)
        d, t = process_image(p)
        print(f"  date={d} total={t}", file=sys.stderr)
        rows.append((p.name, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}", file=sys.stderr)


if __name__ == "__main__":
    main()
