DATE_ISO_RE = re.compile(r"(?<!\d)(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})(?!\d)")
DATE_TEXT_RE = re.compile(r"(?<!\d)(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})(?!\d)")
TIME_RE = re.compile(r"\b\d{1,2}[:.]\d{2}(?:[:.]\d{2})?\s*(?:AM|PM|am|pm)?\b")


