AMOUNT_RE = re.compile(
    r"(?:(?:RM|RN|R\$|\$)\s*)?"
    r"(-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?"
    r"|-?\d+[.,:;]\d{1,2}(?!\d)"
    r"|-?\d+)"
