def _has_digit(line: str) -> bool:
    return bool(re.search(r"\d", line))


TIER_PATTERNS = [
    # Tier 1: GRAND TOTAL (plus common OCR corruption variants)
    [re.compile(r"\bGRAND\s*TOTA[LI1]?\b", re.IGNORECASE),
     re.compile(r"\bGRANDTOTAL\b", re.IGNORECASE)],
    # Tier 2: TOTAL RM / TOTAL: RM / TOTAL(RM) — a few OCR-friendly RM variants
    [re.compile(r"\bTOTAL\b[\s:()\-]{0,4}R[MNH]\b", re.IGNORECASE)],
    # Tier 3: TOTAL AMOUNT
    [re.compile(r"\bTOTAL\s*AMOUNT\b", re.IGNORECASE)],
    # Tier 4: broader TOTAL / DUE variants
    [re.compile(r"\bTOTAL\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bAMOUNT\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bBALANCE\s*DUE\b", re.IGNORECASE),
     re.compile(r"\bNETT?\s*TOTAL\b", re.IGNORECASE),
     re.compile(r"\bTOTAL\b", re.IGNORECASE)],
]

PLAIN_EXCLUSIONS = re.compile(
    r"\b("
    r"SUB[\s\-]?TOTAL|"
    r"DISCOUNT|"
    r"CHANGE|"
    r"CASH\s*TENDERED|CASH\s*RECEIVED|CASH\s*PAYMENT|"
    r"SAVING|SAVINGS|"
    r"EXCLUDING|EXCL\.?\s*(GST|SST|TAX)|"
    r"TOTAL\s*(ITEM|ITEMS|QTY|QUANTITY)|"
    r"ITEM\s*COUNT|NO\s*OF\s*ITEMS|"
    r"TOTAL\s*(GST|SST|TAX)|"
    r"(GST|SST|TAX)\s*TOTAL|"
    r"TAX\s*CODE|GST\s*CODE|"
    r"SPEC\.?\s*DISC|"
    r"ROUNDING\s*ADJ"
    r")\b",
    re.IGNORECASE,
)

SUMMARY_TRIGGER_RE = re.compile(
    r"\b(GST|SST|TAX)\s*(SUMMARY|CODE)\b",
    re.IGNORECASE,
)

COLUMN_HEADER_HINT_RE = re.compile(
    r"\b(QTY|ITEM|DESCRIPTION|DESC|S/PRICE|U\.?PRICE|U/P|UNIT\s*PRICE|CODE)\b",
    re.IGNORECASE,
)


def line_is_excluded(line: str) -> bool:
    return bool(PLAIN_EXCLUSIONS.search(line))


def line_is_column_header(line: str) -> bool:
    """Heuristic: column headers have keyword hints and no numeric values."""
    return bool(COLUMN_HEADER_HINT_RE.search(line)) and not _has_digit(line)


def classify_lines(lines):
    """Yield (idx, line, excluded, in_summary). Once summary begins, it is sticky."""
    in_summary = False
    for i, ln in enumerate(lines):
        if SUMMARY_TRIGGER_RE.search(ln):
            in_summary = True
        yield i, ln, line_is_excluded(ln), in_summary


def extract_total(text: str):
    lines = text.splitlines()
    classified = list(classify_lines(lines))
    n = len(lines)

    for tier in TIER_PATTERNS:
        same_line = []
        split_line = []
        for i, line, excluded, in_summary in classified:
            if in_summary or excluded:
                continue
            if not any(pat.search(line) for pat in tier):
                continue
            if line_is_column_header(line):
                continue
            amounts = _amounts_in_line(line)
            if amounts:
                same_line.append((i, amounts[-1]))
                continue
            # Fallback: last amount on the next non-empty line when this line
            # carries only the label and no usable amount.
            for j in range(i + 1, min(i + 3, n)):
                nxt = lines[j].strip()
                if not nxt:
                    continue
                if line_is_column_header(nxt):
                    break
                nxt_amounts = _amounts_in_line(nxt)
                if nxt_amounts:
                    split_line.append((i, nxt_amounts[-1]))
                break
        if same_line:
            return same_line[-1][1]
        if split_line:
            return split_line[-1][1]
    return None


# ---------- Aggregation across variants ----------

def pick_date(all_scored):
    """Pick best date by total score across variants; tie-break by frequency."""
    totals = {}
    freq = {}
    first_seen = {}
    for var_idx, scored in enumerate(all_scored):
        picked = set()
        for score, ymd in scored:
            totals[ymd] = totals.get(ymd, 0) + score
            if ymd not in first_seen:
                first_seen[ymd] = var_idx
            picked.add(ymd)
        for ymd in picked:
            freq[ymd] = freq.get(ymd, 0) + 1
    if not totals:
        return None
    ranked = sorted(
        totals.items(),
        key=lambda kv: (-kv[1], -freq[kv[0]], first_seen[kv[0]]),
    )
    y, mo, d = ranked[0][0]
    return f"{y:04d}-{mo:02d}-{d:02d}"


def pick_total(values):
    seen = {}
    counts = {}
    for idx, v in enumerate(values):
        if v is None:
            continue
        counts[v] = counts.get(v, 0) + 1
        if v not in seen:
            seen[v] = idx
    if not counts:
        return None
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], seen[kv[0]]))
    return ranked[0][0]


def process_image(path: Path):
    results = ocr_variants(path)
    scored_dates = [score_dates(txt) for _, txt in results]
    totals = [extract_total(txt) for _, txt in results]
    return pick_date(scored_dates), pick_total(totals)


def main():
    rows = []
    files = sorted(IMG_DIR.iterdir(), key=lambda p: p.name)
    for p in files:
        if p.suffix.lower() not in {".png", ".jpg", ".jpeg"}:
            continue
        print(f"Processing {p.name}...", file=sys.stderr)
        d, t = process_image(p)
        print(f"  date={d} total={t}", file=sys.stderr)
        rows.append((p.name, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}", file=sys.stderr)


if __name__ == "__main__":
    main()
