import sys
from datetime import date as date_type
from pathlib import Path

import pytesseract
from PIL import Image, ImageFilter, ImageOps
from openpyxl import Workbook


IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")


# ---------- OCR ----------

def preprocess_variants(img: Image.Image):
    g = ImageOps.grayscale(img)
    ac = ImageOps.autocontrast(g)
    yield ("gray_ac_psm6", ac, "--psm 6")
    yield ("gray_ac_psm4", ac, "--psm 4")
    yield ("gray_ac_sharp_psm6", ac.filter(ImageFilter.SHARPEN), "--psm 6")
    yield ("raw_default", img, "")
    if min(img.size) < 1200:
        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        yield ("up2_psm6", big, "--psm 6")
        yield ("up2_psm4", big, "--psm 4")


def clean_line(line: str) -> str:
    """Normalise whitespace glitches that break numeric parsing."""
    line = re.sub(r"(\d)\s*\.\s+(\d)", r"\1.\2", line)
    line = re.sub(r"(\d)\s+\.\s*(\d)", r"\1.\2", line)
    line = re.sub(r"(\d)\s*,\s+(\d)", r"\1,\2", line)
    line = re.sub(r"(\d)\s*[:;]\s+(\d{2})\b", r"\1.\2", line)
    return line


def ocr_variants(img_path: Path):
    img = Image.open(img_path)
    out = []
    for label, im, psm in preprocess_variants(img):
        try:
            txt = pytesseract.image_to_string(im, lang="eng", config=psm)
        except Exception:
            txt = ""
        if txt and txt.strip():
            lines = [clean_line(ln) for ln in txt.splitlines()]
            out.append((label, "\n".join(lines)))
    return out


